import * as THREE from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  const materials = [];
  const geometries = [];

  // Load and configure watch mesh
  const watchGltf = ctx.glbLoader.load(config.meshUrl);
  const watchMesh = watchGltf.scene.clone();

  watchMesh.traverse((child) => {
    if (child.isMesh) {
      const mat = new THREE.MeshStandardMaterial({
        color: child.material?.color || new THREE.Color(0xcccccc),
        map: child.material?.map,
        normalMap: child.material?.normalMap,
        roughnessMap: child.material?.roughnessMap,
        metalnessMap: child.material?.metalnessMap,
        roughness: 0.52,
        metalness: 0.55,
        clearcoat: 0.2,
        clearcoatRoughness: 0.4,
      });
      materials.push(mat);
      child.material = mat;
    }
  });

  group.add(watchMesh);

  // Plinth (cylindrical base, radius 1.4, height 0.25, top at y=-1.1)
  const plinthGeom = new THREE.CylinderGeometry(1.4, 1.4, 0.25, 64);
  geometries.push(plinthGeom);
  const plinthMat = new THREE.MeshStandardMaterial({
    color: new THREE.Color('#14141a'),
    roughness: 0.7,
    metalness: 0.3,
  });
  materials.push(plinthMat);
  const plinth = new THREE.Mesh(plinthGeom, plinthMat);
  plinth.position.y = -1.1;
  group.add(plinth);

  // Backdrop plane (7x6 units at z=-2.5, gradient reference)
  const backdropGeom = new THREE.PlaneGeometry(7, 6);
  geometries.push(backdropGeom);
  const backdropMat = new THREE.MeshStandardMaterial({
    color: new THREE.Color('#16161d'),
    side: THREE.DoubleSide,
  });
  materials.push(backdropMat);
  const backdrop = new THREE.Mesh(backdropGeom, backdropMat);
  backdrop.position.z = -2.5;
  group.add(backdrop);

  // Contact shadow (radial gradient plane under plinth)
  const shadowGeom = new THREE.PlaneGeometry(3.2, 3.2);
  geometries.push(shadowGeom);
  const shadowMat = new THREE.MeshStandardMaterial({
    color: new THREE.Color(0x000000),
    transparent: true,
    opacity: 0.35,
  });
  materials.push(shadowMat);
  const shadow = new THREE.Mesh(shadowGeom, shadowMat);
  shadow.position.set(0, -1.105, 0);
  group.add(shadow);

  // Text: headline, body, caption via MSDF font atlas
  if (config.textContent?.length > 0) {
    // Headline: "Calibre NA-01" (baseline 1.5 units below center)
    const headline = ctx.fontAtlas.render(config.textContent[0], {
      font: 'Lora',
      fontSize: 68,
      fontWeight: 600,
      color: new THREE.Color('#e8ecf2'),
    });
    headline.position.y = -1.5;
    group.add(headline);

    // Body: "Machined in-house..."
    if (config.textContent[1]) {
      const body = ctx.fontAtlas.render(config.textContent[1], {
        font: 'JetBrains Mono',
        fontSize: 26,
        fontWeight: 400,
        color: new THREE.Color('#e8ecf2'),
      });
      body.position.y = -1.75;
      group.add(body);
    }

    // Caption: "FROM 4200 USD..." (0.5 units below headline)
    if (config.textContent[2]) {
      const caption = ctx.fontAtlas.render(config.textContent[2], {
        font: 'JetBrains Mono',
        fontSize: 18,
        fontWeight: 400,
        color: new THREE.Color('#ff2a38'),
      });
      caption.position.y = -2.0;
      group.add(caption);
    }
  }

  // Accent rim light (grazes left case flank with #ff2a38 highlight)
  const rimLight = new THREE.PointLight(new THREE.Color('#ff2a38'), 1.0, 5);
  rimLight.position.set(-1.5, 0.2, 0.5);
  group.add(rimLight);

  // Key light
  const keyLight = new THREE.DirectionalLight(new THREE.Color('#ffffff'), 1.2);
  keyLight.position.set(1, 2, 2);
  group.add(keyLight);

  // Apply cinematic primitives (orbit on load, depth-rotate on hover)
  if (config.cinematicPrimitives?.length > 0) {
    for (const primitive of config.cinematicPrimitives) {
      if (ctx.primitives[primitive.name]) {
        ctx.primitives[primitive.name](watchMesh, primitive.params);
      }
    }
  }

  // Cleanup: dispose geometries and materials
  group.userData.cleanup = () => {
    geometries.forEach(g => g.dispose());
    materials.forEach(m => m.dispose());
  };

  // Event handlers
  group.userData.handlers = {};

  return group;
}
